348: static int korina_rx(struct net_device *dev, int limit)
349: {
350: 	struct korina_private *lp = netdev_priv(dev);
351: 	struct dma_desc *rd = &lp->rd_ring[lp->rx_next_done];
352: 	struct sk_buff *skb, *skb_new;
353: 	u8 *pkt_buf;
